import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Tech Talk: Ceph at DigitalOcean","description":"","frontmatter":{"title":"Ceph Tech Talk: Ceph at DigitalOcean","date":"2021-10-07T00:00:00.000Z","updated":"2021-10-08T00:00:00.000Z","tags":["Ceph","Distributed Storage","DigitalOcean","Cloud Computing","Storage Systems"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Tech_Talk_-_Ceph_at_DigitalOcean.md","filePath":"posts/2021/Ceph_Tech_Talk_-_Ceph_at_DigitalOcean.md","lastUpdated":1780459816000}'),r={name:"posts/2021/Ceph_Tech_Talk_-_Ceph_at_DigitalOcean.md"};function o(n,a,h,s,p,c){return l(),i("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-digitalocean-的-ceph-使用案例介绍" tabindex="-1">会议主题：DigitalOcean 的 Ceph 使用案例介绍 <a class="header-anchor" href="#会议主题-digitalocean-的-ceph-使用案例介绍" aria-label="Permalink to &quot;会议主题：DigitalOcean 的 Ceph 使用案例介绍&quot;">​</a></h4><h4 id="会议时间-具体日期" tabindex="-1">会议时间：[具体日期] <a class="header-anchor" href="#会议时间-具体日期" aria-label="Permalink to &quot;会议时间：[具体日期]&quot;">​</a></h4><h4 id="会议地点-线上-线下" tabindex="-1">会议地点：[线上/线下] <a class="header-anchor" href="#会议地点-线上-线下" aria-label="Permalink to &quot;会议地点：[线上/线下]&quot;">​</a></h4><h4 id="主讲人-alex-merrigan" tabindex="-1">主讲人：Alex Merrigan <a class="header-anchor" href="#主讲人-alex-merrigan" aria-label="Permalink to &quot;主讲人：Alex Merrigan&quot;">​</a></h4><ul><li><strong>职位</strong>：Senior Engineer at DigitalOcean</li><li><strong>团队</strong>：Storage Systems Team</li></ul><h4 id="会议内容概述" tabindex="-1">会议内容概述： <a class="header-anchor" href="#会议内容概述" aria-label="Permalink to &quot;会议内容概述：&quot;">​</a></h4><p>Alex Merrigan 介绍了 DigitalOcean 在存储系统中使用 Ceph 的情况，包括公司简介、Ceph 的部署与运维、自动化工具的使用以及遇到的问题和挑战。</p><h4 id="关键细节" tabindex="-1">关键细节： <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节：&quot;">​</a></h4><ol><li><p><strong>DigitalOcean 简介</strong>：</p><ul><li>成立于 [具体年份]，以简化云资源配置为核心理念。</li><li>产品包括 Droplets（虚拟机）、Block Storage、Spaces（对象存储平台）等。</li><li>全球八个区域的数据中心，最近完成 IPO。</li></ul></li><li><p><strong>Ceph 使用情况</strong>：</p><ul><li>用于 Block 和 Object 存储产品，总计 38 个生产集群，37 个在 Nautilus，1 个在 Luminous。</li><li>总存储量超过 54 PB，包括全闪存和混合存储（HDD 和 QRC Flash）。</li></ul></li><li><p><strong>选择 Ceph 的原因</strong>：</p><ul><li>水平扩展、自愈能力、强一致性、性能可接受、支持多种存储产品。</li></ul></li><li><p><strong>Ceph 操作流程</strong>：</p><ul><li>高度自动化，使用 Ansible Playbooks 和 AWX。</li><li>容器化部署，监控使用 Ceph Exporter 和 Node Exporter。</li><li>自动化工具如 Archimedes 和 PgRemapper。</li></ul></li><li><p><strong>遇到的问题</strong>：</p><ul><li>Ceph 升级过程中文档不足，动态重新分片可能导致 RGW 线程耗尽，Beast 后端默认线程设置可能不足。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>优化 Ceph 的自动化和监控工具。</li><li>加强 Ceph 升级和测试流程的改进。</li><li>考虑将更多产品迁移到 Ceph。</li></ul><h4 id="其他信息" tabindex="-1">其他信息： <a class="header-anchor" href="#其他信息" aria-label="Permalink to &quot;其他信息：&quot;">​</a></h4><ul><li>DigitalOcean 正在招聘，感兴趣的候选人可以查看招聘页面。</li><li>如有关于会议内容的疑问，可以联系 Alex Merrigan。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><p>感谢所有参与者的参与，祝大家有一个愉快的一天。</p>',16)])])}const g=e(r,[["render",o]]);export{u as __pageData,g as default};
